//! The general AV2 decoder's probability models: every AVM v1.0.0 default
//! its syntax reads so far, with AVM's adaptation rates (generated by
//! `tools/codegen/gen_av2_general_cdfs.py`, which tool agents extend).
//!
//! Kept apart from [`crate::cdf_models::TileCdfs`], the encoder's subset,
//! so the encoder's hot model copies stay small; both use the shared
//! [`Cdf`] and entropy reader.
use crate::entropy::Cdf;
#[path = "cdfs/defaults.rs"]
mod defaults;
#[derive(Clone, Copy)]
struct Initial<const N: usize> {
    inverse: [u16; N],
    rates: [u8; 3],
}
impl<const N: usize> Initial<N> {
    fn build(self) -> Cdf<N> {
        Cdf::new(self.inverse, self.rates).expect("independently verified AVM defaults")
    }
}
/// The coefficient CDF quantizer category of a frame base qindex (AVM `get_q_ctx`).
#[allow(dead_code, reason = "the coefficient families use it")]
fn category(qindex: u16) -> usize {
    match qindex {
        0..=90 => 0,
        91..=140 => 1,
        141..=190 => 2,
        _ => 3,
    }
}
/// One tile's models.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Cdfs {
    /// Whether a block splits (plane tree, context) (AVM `default_do_split_cdf[a][b]`).
    pub part_split: [[Cdf<2>; 64]; 2],
    /// Whether a 128x128 or 256x256 block splits into four squares (AVM `default_do_square_split_cdf[0][a]`).
    pub part_square: [Cdf<2>; 8],
    /// The direction of a binary split (AVM `default_rect_type_cdf[a][b]`).
    pub part_dir: [[Cdf<2>; 64]; 2],
    /// Whether a split is three-way (AVM `default_do_ext_partition_cdf[a][0][b]`).
    pub part_ext: [[Cdf<2>; 64]; 2],
    /// Whether a three-way split is the uneven four-way one instead (AVM `default_do_uneven_4way_partition_cdf[a][0][b]`).
    pub part_4way: [[Cdf<2>; 64]; 2],
    /// Whether an inter-frame region is intra only (separate trees) (AVM `default_region_type_cdf[a]`).
    pub region_type: [Cdf<2>; 4],
    /// Whether an inter block is in skip mode (AVM `default_skip_mode_cdfs[a]`).
    pub skip_mode: [Cdf<2>; 3],
    /// Whether a block of an inter frame is inter (AVM `default_intra_inter_cdf[a]`).
    pub is_inter: [Cdf<2>; 4],
    /// Whether an intra block uses intra block copy (AVM `default_intrabc_cdf[a]`).
    pub intrabc: [Cdf<2>; 3],
    /// Whether a block has no residual (contexts 3..5 in skip mode) (AVM `default_skip_txfm_cdfs[a]`).
    pub skip_txfm: [Cdf<2>; 6],
    /// Whether a guided-detail-filter block is filtered (AVM `default_gdf_cdf`).
    pub gdf: Cdf<2>,
    /// Whether a CDEF block uses strength set 0 (AVM `default_cdef_strength_index0_cdf[a]`).
    pub cdef_index0: [Cdf<2>; 4],
    /// The CDEF strength set beyond 0 of a frame with three sets (AVM `default_cdef_cdf[0]`).
    pub cdef_index3: Cdf<2>,
    /// The same with four sets (AVM `default_cdef_cdf[1]`).
    pub cdef_index4: Cdf<3>,
    /// The same with five sets (AVM `default_cdef_cdf[2]`).
    pub cdef_index5: Cdf<4>,
    /// The same with six sets (AVM `default_cdef_cdf[3]`).
    pub cdef_index6: Cdf<5>,
    /// The same with seven sets (AVM `default_cdef_cdf[4]`).
    pub cdef_index7: Cdf<6>,
    /// The same with eight sets (AVM `default_cdef_cdf[5]`).
    pub cdef_index8: Cdf<7>,
    /// Whether a CCSO block of a plane is filtered (AVM `default_ccso_cdf[a][b]`).
    pub ccso: [[Cdf<2>; 4]; 3],
    /// A superblock quantizer delta (the last symbol escapes) (AVM `default_delta_q_cdf`).
    pub delta_q: Cdf<8>,
}
impl Cdfs {
    /// The defaults of a frame at base quantizer `qindex`.
    #[must_use]
    pub fn new(qindex: u16) -> Self {
        #[allow(unused_variables, reason = "the coefficient families use it")]
        let q = category(qindex);
        Self {
            part_split: defaults::PART_SPLIT.map(|value| value.map(Initial::build)),
            part_square: defaults::PART_SQUARE.map(Initial::build),
            part_dir: defaults::PART_DIR.map(|value| value.map(Initial::build)),
            part_ext: defaults::PART_EXT.map(|value| value.map(Initial::build)),
            part_4way: defaults::PART_4WAY.map(|value| value.map(Initial::build)),
            region_type: defaults::REGION_TYPE.map(Initial::build),
            skip_mode: defaults::SKIP_MODE.map(Initial::build),
            is_inter: defaults::IS_INTER.map(Initial::build),
            intrabc: defaults::INTRABC.map(Initial::build),
            skip_txfm: defaults::SKIP_TXFM.map(Initial::build),
            gdf: defaults::GDF.build(),
            cdef_index0: defaults::CDEF_INDEX0.map(Initial::build),
            cdef_index3: defaults::CDEF_INDEX3.build(),
            cdef_index4: defaults::CDEF_INDEX4.build(),
            cdef_index5: defaults::CDEF_INDEX5.build(),
            cdef_index6: defaults::CDEF_INDEX6.build(),
            cdef_index7: defaults::CDEF_INDEX7.build(),
            cdef_index8: defaults::CDEF_INDEX8.build(),
            ccso: defaults::CCSO.map(|value| value.map(Initial::build)),
            delta_q: defaults::DELTA_Q.build(),
        }
    }
    /// Move every model back along its adaptation-rate schedule (AVM
    /// `av2_reset_cdf_symbol_counters`) before later frames inherit them.
    pub fn restart_adaptation(&mut self) {
        for v0 in &mut self.part_split {
            for v1 in v0 {
                v1.restart_adaptation();
            }
        }
        for v0 in &mut self.part_square {
            v0.restart_adaptation();
        }
        for v0 in &mut self.part_dir {
            for v1 in v0 {
                v1.restart_adaptation();
            }
        }
        for v0 in &mut self.part_ext {
            for v1 in v0 {
                v1.restart_adaptation();
            }
        }
        for v0 in &mut self.part_4way {
            for v1 in v0 {
                v1.restart_adaptation();
            }
        }
        for v0 in &mut self.region_type {
            v0.restart_adaptation();
        }
        for v0 in &mut self.skip_mode {
            v0.restart_adaptation();
        }
        for v0 in &mut self.is_inter {
            v0.restart_adaptation();
        }
        for v0 in &mut self.intrabc {
            v0.restart_adaptation();
        }
        for v0 in &mut self.skip_txfm {
            v0.restart_adaptation();
        }
        self.gdf.restart_adaptation();
        for v0 in &mut self.cdef_index0 {
            v0.restart_adaptation();
        }
        self.cdef_index3.restart_adaptation();
        self.cdef_index4.restart_adaptation();
        self.cdef_index5.restart_adaptation();
        self.cdef_index6.restart_adaptation();
        self.cdef_index7.restart_adaptation();
        self.cdef_index8.restart_adaptation();
        for v0 in &mut self.ccso {
            for v1 in v0 {
                v1.restart_adaptation();
            }
        }
        self.delta_q.restart_adaptation();
    }
}
#[cfg(test)]
mod tests {
    use super::*;
    use crate::entropy::Writer;
    fn trace<const N: usize>(cdf: &mut Cdf<N>, hash: &mut u64) {
        let mut writer = Writer::new();
        for step in 0..65 {
            writer.symbol((step * 7 + step / 3) % N, cdf).unwrap();
            for &value in cdf.inverse() {
                *hash = (*hash ^ u64::from(value)).wrapping_mul(1_099_511_628_211);
            }
        }
    }
    /// Our models update as AVM's `update_cdf` does, from the same defaults.
    #[test]
    fn original_c_update_traces() {
        for (q, expected) in [0, 91, 141, 191].into_iter().zip(defaults::TRACE_HASHES) {
            let mut models = Cdfs::new(q);
            let mut hash = 14_695_981_039_346_656_037;
            for v0 in &mut models.part_split {
                for v1 in v0 {
                    trace(v1, &mut hash);
                }
            }
            for v0 in &mut models.part_square {
                trace(v0, &mut hash);
            }
            for v0 in &mut models.part_dir {
                for v1 in v0 {
                    trace(v1, &mut hash);
                }
            }
            for v0 in &mut models.part_ext {
                for v1 in v0 {
                    trace(v1, &mut hash);
                }
            }
            for v0 in &mut models.part_4way {
                for v1 in v0 {
                    trace(v1, &mut hash);
                }
            }
            for v0 in &mut models.region_type {
                trace(v0, &mut hash);
            }
            for v0 in &mut models.skip_mode {
                trace(v0, &mut hash);
            }
            for v0 in &mut models.is_inter {
                trace(v0, &mut hash);
            }
            for v0 in &mut models.intrabc {
                trace(v0, &mut hash);
            }
            for v0 in &mut models.skip_txfm {
                trace(v0, &mut hash);
            }
            trace(&mut models.gdf, &mut hash);
            for v0 in &mut models.cdef_index0 {
                trace(v0, &mut hash);
            }
            trace(&mut models.cdef_index3, &mut hash);
            trace(&mut models.cdef_index4, &mut hash);
            trace(&mut models.cdef_index5, &mut hash);
            trace(&mut models.cdef_index6, &mut hash);
            trace(&mut models.cdef_index7, &mut hash);
            trace(&mut models.cdef_index8, &mut hash);
            for v0 in &mut models.ccso {
                for v1 in v0 {
                    trace(v1, &mut hash);
                }
            }
            trace(&mut models.delta_q, &mut hash);
            assert_eq!(hash, expected);
        }
    }
}
